  const subjectKey = (sub) => sub.kind === 'plant' ? 'plant' : `${sub.kind}:${sub.id}`;
  const parseNode = (key) => key === 'plant' ? { kind: 'plant' } : { kind: key.split(':')[0], id: key.split(':')[1] };
  const sensorHome = (s) => s.on.startsWith('pipe:') ? (pipe(s.on.slice(5)) || { id: s.on.slice(5), tag: '?', name: 'a pipe no longer drawn', stage: null, type: 'Pipe', tier: 'B', isPipe: true }) : eq(s.on.slice(3));
