  const connOf = (e, id) => connectionsOf(e).find((x) => x.conn.id === id) || null;
  const findReading = (e, on, kind) => { if (!e) return null; if (!on || on === 'self') return sensorsOf({ kind: 'eq', id: e.id }).find((x) => x.name === kind) || null; const x = connOf(e, on); if (!x || !x.bound) return null; return x.readings.find((y) => y.name === kind) || null; };
  const connWhy = (e, on, kind) => { const x = connOf(e, on); const nm = x ? x.conn.name.toLowerCase() : on; if (!x) return `a ${e.type.toLowerCase()} declares no ${nm}`; if (x.by === 'choose') return `choose its ${nm} first: SCADA draws ${x.candidates.length} candidates`; if (!x.bound) return `needs its ${nm}: not drawn in SCADA, or choose it on the machine`; return `${x.tags.join(', ')} has no ${kind} widget`; };
  const connWords = (e, id, how) => { const x = e ? connOf(e, id) : null; if (!x || !x.bound) return how === 'count' ? '0' : `the ${x ? x.conn.name.toLowerCase() : id}`; if (how === 'count') return String(x.to.length); const names = x.to.map(targetTag); const j = x.conn.kind === 'peer' ? ' or ' : ' and '; return names.length === 1 ? names[0] : names.length === 2 ? names.join(j) : names.slice(0, -1).join(', ') + j + names.at(-1); };
  const resolveText = (text, e) => String(text).replace(/\{\{(\w+)(?:\.(\w+))?\}\}/g, (m, id, how) => id === 'self' ? (e ? e.tag : 'the machine') : connWords(e, id, how));
  const resolveSteps = (f, e) => (f ? f.steps : []).map((st) => { const out = { ...st, text: resolveText(st.text, e), skipped: false, why: '' }; if (st.only) { const x = e ? connOf(e, st.only) : null; if (!x || !x.bound) { out.skipped = true; out.why = e ? `no ${x ? x.conn.name.toLowerCase() : st.only} at this plant` : `needs a machine with a ${st.only}`; } } if (st.on && e && !out.skipped) { const rd = findReading(e, st.on, st.sensorKind); out.sensor = rd ? rd.id : null; if (!rd) { const x = connOf(e, st.on); out.skipped = true; out.why = x && x.bound ? `${x.tags.join(', ')} has no ${st.sensorKind} widget` : `no ${x ? x.conn.name.toLowerCase() : st.on} at this plant`; } } return out; });
